    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 1]
    sixes = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 6]
    # Interpolate diagonal lines joining aligned 1 markers.
    for i,(r1,c1) in enumerate(ones):
        for r2,c2 in ones[i+1:]:
            dr,dc=r2-r1,c2-c1
            if dr and abs(dr)==abs(dc):
                sr=1 if dr>0 else -1; sc=1 if dc>0 else -1
                for k in range(1,abs(dr)):
                    r,c=r1+k*sr,c1+k*sc
                    if out[r][c]==4: out[r][c]=1
    # Each 6 lying on a completed 1 diagonal is the center of a full,
    # oppositely-sloped 6 diagonal extending to the grid edges.
    centers=[]
    for r,c in sixes:
        if any(dr and abs(dr)==abs(dc) and (r-r1)*(c-c1)>=0 and
               abs(r-r1)==abs(c-c1) and min(r1,r2)<=r<=max(r1,r2)
               for i,(r1,c1) in enumerate(ones) for r2,c2 in ones[i+1:]
               for dr,dc in [(r2-r1,c2-c1)]):
            centers.append((r,c))
    for r,c in centers:
        for k in range(-min(r,w-1-c), min(h-1-r,c)+1):
            rr,cc=r+k,c-k
            if out[rr][cc]==4: out[rr][cc]=6
